import { PaymentRepository } from '../repositories/payment-repository.js';
import { OrderRepository } from '../repositories/order-repository.js';

const paymentRepository = new PaymentRepository();
const orderRepository = new OrderRepository();

// Migrated to PaymentRepository; callback signatures are kept for callers.
export function findPaymentsForOrder(orderId, callback, repo = paymentRepository) {
  repo.findByOrder(orderId).then(
    (payments) => callback(null, payments),
    (err) => callback(err),
  );
}

// Payments on the user's non-deleted orders.
export function listPaymentsForUser(userId, callback, repo = paymentRepository, orders = orderRepository) {
  orders.findByUser(userId)
    .then((rows) => repo.findByOrders(rows.map((o) => o.id)))
    .then(
      (payments) => callback(null, payments),
      (err) => callback(err),
    );
}

export function uncapturedTotalCents(callback, repo = paymentRepository) {
  repo.findUncaptured().then(
    (rows) => callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0)),
    (err) => callback(err),
  );
}
